#!/usr/bin/env python3
"""Generate RandLib's distributable single header."""

from __future__ import annotations

import argparse
import re
from pathlib import Path


INTERNAL_INCLUDE = re.compile(r'^\s*#\s*include\s*[<"](?P<name>randlib/[^>"]+)[>"]\s*$')


def amalgamate(include_root: Path, entry: str) -> str:
    emitted: set[Path] = set()
    output = [
        "// RandLib single-header distribution generated by tools/amalgamate.py.",
        "// Include this file instead of <randlib/randlib.hpp>.",
        "#pragma once",
        "",
    ]

    def expand(name: str) -> None:
        path = (include_root / name).resolve()
        try:
            path.relative_to(include_root.resolve())
        except ValueError as error:
            raise ValueError(f"internal include escapes the include root: {name}") from error
        if path in emitted:
            return
        if not path.is_file():
            raise FileNotFoundError(f"internal include does not exist: {name}")
        emitted.add(path)
        output.append(f"// BEGIN {name}")
        for line in path.read_text(encoding="utf-8").splitlines():
            if line.strip() == "#pragma once":
                continue
            match = INTERNAL_INCLUDE.fullmatch(line)
            if match:
                expand(match.group("name"))
            else:
                output.append(line)
        output.extend((f"// END {name}", ""))

    expand(entry)
    return "\n".join(output) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--include-root", type=Path, default=Path("include"))
    parser.add_argument("--entry", default="randlib/randlib.hpp")
    parser.add_argument("--output", type=Path, default=Path("randlib_single.hpp"))
    arguments = parser.parse_args()

    generated = amalgamate(arguments.include_root, arguments.entry)
    arguments.output.parent.mkdir(parents=True, exist_ok=True)
    arguments.output.write_text(generated, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
